 s=re.sub(r'(<script[^>]*type="application/ld\+json"[^>]*>)(.*?)(</script>)',schema,s,flags=re.S)
 faq={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in FAQS]}
 s=s.replace('</head>','<script type="application/ld+json">'+json.dumps(faq,indent=2)+'</script>\n</head>',1);p.write_text(s)
 xml=ROOT/'sitemap-blog.xml';x=xml.read_text();pattern=r'(<loc>https://www\.bnbaccelerator\.com/blog/'+SLUG+r'/</loc>\s*<lastmod>)[^<]*(</lastmod>)';x,n=re.subn(pattern,r'\g<1>2026-10-06\2',x);assert n==1;xml.write_text(x)
